sys_script_include.script:
var ProjectMCPAttachmentServiceSNC = Class.create();
ProjectMCPAttachmentServiceSNC.prototype = {
    initialize: function() {
        this.MAX_ATTACHMENT_SIZE_BYTES = 5 * 1024 * 1024;

        this.ALLOWED_TABLES = [
            'rm_story',
            'pm_project'
        ];
    },

    getAttachment: function(attachmentSysId, attachmentName) {
        try {
            attachmentSysId = this._trim(attachmentSysId);
            attachmentName = this._trim(attachmentName);

            if (!attachmentSysId && !attachmentName) {
                return this._error(
                    400,
                    'Either attachment_sys_id or attachment_name is required.'
                );
            }

            if (attachmentSysId && attachmentName) {
                return this._error(
                    400,
                    'Specify either attachment_sys_id or attachment_name, not both.'
                );
            }

            var lookupResult;

            if (attachmentSysId) {
                lookupResult = this._findBySysId(attachmentSysId);
            } else {
                lookupResult = this._findByName(attachmentName);
            }

            if (!lookupResult.success) {
                return lookupResult;
            }

            var attachmentGR = lookupResult.record;

            var tableName = attachmentGR.getValue('table_name');

            if (!this._isAllowedTable(tableName)) {
                return this._error(
                    403,
                    'Attachments may only be retrieved from Story or Project records.'
                );
            }

            var sizeBytes = parseInt(
                attachmentGR.getValue('size_bytes'),
                10
            );

            if (isNaN(sizeBytes)) {
                return this._error(
                    500,
                    'Unable to determine attachment size.'
                );
            }

            if (sizeBytes > this.MAX_ATTACHMENT_SIZE_BYTES) {
                return this._error(
                    413,
                    'Attachment exceeds the maximum allowed size of 5 MB.'
                );
            }

            var attachmentAPI = new GlideSysAttachment();

            var contentBase64 =
                attachmentAPI.getContentBase64(attachmentGR);

            if (gs.nil(contentBase64)) {
                return this._error(
                    500,
                    'Unable to read attachment content.'
                );
            }

            return {
                success: true,
                status: 200,
                data: {
                    sys_id: attachmentGR.getUniqueValue(),
                    file_name: attachmentGR.getValue('file_name'),
                    content_type: attachmentGR.getValue('content_type'),
                    size_bytes: sizeBytes,
                    table_name: tableName,
                    table_sys_id: attachmentGR.getValue('table_sys_id'),
                    encoding: 'base64',
                    content_base64: contentBase64
                }
            };

        } catch (e) {
            gs.error(
                'ProjectMCPAttachmentServiceSNC.getAttachment error: ' +
                e.message
            );

            return this._error(
                500,
                'Internal error retrieving attachment.'
            );
        }
    },

    addAttachment: function(
        tableName,
        tableSysId,
        fileName,
        contentBase64
    ) {
        try {
            tableName = this._trim(tableName);
            tableSysId = this._trim(tableSysId);
            fileName = this._trim(fileName);

            if (!tableName) {
                return this._error(
                    400,
                    'table_name is required.'
                );
            }

            if (!tableSysId) {
                return this._error(
                    400,
                    'table_sys_id is required.'
                );
            }

            if (!fileName) {
                return this._error(
                    400,
                    'file_name is required.'
                );
            }

            if (gs.nil(contentBase64)) {
                return this._error(
                    400,
                    'content_base64 is required.'
                );
            }

            if (!this._isAllowedTable(tableName)) {
                return this._error(
                    403,
                    'Attachments may only be added to Story or Project records.'
                );
            }

            if (!this._isValidSysId(tableSysId)) {
                return this._error(
                    400,
                    'table_sys_id must be a valid 32-character sys_id.'
                );
            }

            var normalizedBase64 =
                String(contentBase64).replace(/\s/g, '');

            if (!normalizedBase64) {
                return this._error(
                    400,
                    'content_base64 is required.'
                );
            }

            var decodedSize =
                this._getDecodedBase64Size(normalizedBase64);

            if (decodedSize < 0) {
                return this._error(
                    400,
                    'content_base64 is not valid Base64 data.'
                );
            }

            if (decodedSize > this.MAX_ATTACHMENT_SIZE_BYTES) {
                return this._error(
                    413,
                    'Attachment exceeds the maximum allowed size of 5 MB.'
                );
            }

            var targetGR = new GlideRecordSecure(tableName);

            if (!targetGR.get(tableSysId)) {
                return this._error(
                    404,
                    'Target record not found.'
                );
            }

            if (!targetGR.canWrite()) {
                return this._error(
                    403,
                    'Write access to the target record is required to add an attachment.'
                );
            }

            var contentType =
                this._getContentTypeFromFileName(fileName);

            var attachmentAPI = new GlideSysAttachment();

            var attachmentSysId = attachmentAPI.writeBase64(
                targetGR,
                fileName,
                contentType,
                normalizedBase64
            );

            if (gs.nil(attachmentSysId)) {
                return this._error(
                    500,
                    'Unable to create attachment.'
                );
            }

            /*
             * Read the new attachment record back so the response
             * contains the metadata stored by the platform.
             */
            var attachmentGR =
                new GlideRecordSecure('sys_attachment');

            if (attachmentGR.get(attachmentSysId)) {
                var storedSize = parseInt(
                    attachmentGR.getValue('size_bytes'),
                    10
                );

                if (isNaN(storedSize)) {
                    storedSize = decodedSize;
                }

                return {
                    success: true,
                    status: 201,
                    data: {
                        sys_id: attachmentGR.getUniqueValue(),
                        file_name: attachmentGR.getValue('file_name'),
                        content_type: attachmentGR.getValue('content_type'),
                        size_bytes: storedSize,
                        table_name: attachmentGR.getValue('table_name'),
                        table_sys_id: attachmentGR.getValue('table_sys_id')
                    }
                };
            }

            /*
             * The attachment was successfully created even if the
             * new sys_attachment record cannot be read back.
             */
            return {
                success: true,
                status: 201,
                data: {
                    sys_id: String(attachmentSysId),
                    file_name: fileName,
                    content_type: contentType,
                    size_bytes: decodedSize,
                    table_name: tableName,
                    table_sys_id: tableSysId
                }
            };

        } catch (e) {
            gs.error(
                'ProjectMCPAttachmentServiceSNC.addAttachment error: ' +
                e.message
            );

            return this._error(
                500,
                'Internal error adding attachment.'
            );
        }
    },

    _findBySysId: function(attachmentSysId) {
        var gr = new GlideRecordSecure('sys_attachment');

        if (!gr.get(attachmentSysId)) {
            return this._error(
                404,
                'Attachment not found.'
            );
        }

        /*
         * Do the table check here as well so attachments from
         * unrelated tables are rejected before any content is read.
         */
        if (!this._isAllowedTable(gr.getValue('table_name'))) {
            return this._error(
                403,
                'Attachments may only be retrieved from Story or Project records.'
            );
        }

        return {
            success: true,
            status: 200,
            record: gr
        };
    },

    _findByName: function(attachmentName) {
        var gr = new GlideRecordSecure('sys_attachment');

        gr.addQuery(
            'table_name',
            'IN',
            this.ALLOWED_TABLES.join(',')
        );

        gr.addQuery('file_name', attachmentName);

        /*
         * We only need to know whether there is zero, one,
         * or more than one matching attachment.
         */
        gr.setLimit(2);
        gr.query();

        if (!gr.next()) {
            return this._error(
                404,
                'Attachment not found.'
            );
        }

        var firstSysId = gr.getUniqueValue();

        if (gr.next()) {
            return this._error(
                409,
                'Multiple attachments with that filename exist. Use attachment_sys_id instead.'
            );
        }

        var result = new GlideRecordSecure('sys_attachment');

        if (!result.get(firstSysId)) {
            return this._error(
                404,
                'Attachment not found.'
            );
        }

        return {
            success: true,
            status: 200,
            record: result
        };
    },

    _isAllowedTable: function(tableName) {
        for (var i = 0; i < this.ALLOWED_TABLES.length; i++) {
            if (tableName === this.ALLOWED_TABLES[i]) {
                return true;
            }
        }

        return false;
    },

    _isValidSysId: function(value) {
        return /^[0-9a-fA-F]{32}$/.test(value);
    },

    _getDecodedBase64Size: function(contentBase64) {
        if (!contentBase64) {
            return -1;
        }

        if (contentBase64.length % 4 !== 0) {
            return -1;
        }

        if (!/^[A-Za-z0-9+\/]*={0,2}$/.test(contentBase64)) {
            return -1;
        }

        var padding = 0;

        if (contentBase64.length >= 1 &&
            contentBase64.charAt(contentBase64.length - 1) === '=') {
            padding++;
        }

        if (contentBase64.length >= 2 &&
            contentBase64.charAt(contentBase64.length - 2) === '=') {
            padding++;
        }

        return (contentBase64.length * 3 / 4) - padding;
    },

    _getContentTypeFromFileName: function(fileName) {
        var lowerName = String(fileName).toLowerCase();
        var dotIndex = lowerName.lastIndexOf('.');

        if (dotIndex < 0 || dotIndex === lowerName.length - 1) {
            return 'application/octet-stream';
        }

        var extension = lowerName.substring(dotIndex + 1);

        var contentTypes = {
            'png': 'image/png',
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg',
            'gif': 'image/gif',
            'webp': 'image/webp',
            'bmp': 'image/bmp',
            'svg': 'image/svg+xml',

            'txt': 'text/plain',
            'md': 'text/markdown',
            'csv': 'text/csv',
            'html': 'text/html',
            'htm': 'text/html',
            'css': 'text/css',

            'json': 'application/json',
            'xml': 'application/xml',
            'js': 'application/javascript',

            'pdf': 'application/pdf',
            'zip': 'application/zip',

            'doc': 'application/msword',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xls': 'application/vnd.ms-excel',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'ppt': 'application/vnd.ms-powerpoint',
            'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
        };

        return contentTypes[extension] ||
            'application/octet-stream';
    },

    _trim: function(value) {
        if (gs.nil(value)) {
            return '';
        }

        return String(value).replace(/^\s+|\s+$/g, '');
    },

    _error: function(status, message) {
        return {
            success: false,
            status: status,
            error: message
        };
    },

    type: 'ProjectMCPAttachmentServiceSNC'
};
